@pytest.mark.unit
def test_tc_o6_07_market_ordinary_and_wrap_up(tmp_path, monkeypatch, offline):
    plan = build_analyst_execution_plan(["market"])
    keys = {spec.key for spec in plan.specs}
    clock = FakeClock()
    recorder = Recorder()
    handler = StatsCallbackHandler(selected_analyst_keys=keys, clock=clock)
    model = ScriptedModel(
        usages=[Usage(100, 20, 1.0), Usage(80, 15, 0.5)],
        clock=clock,
    )
    # Advance the clock when each call is issued so the handler sees 1.0 / 0.5 s.
    marks = iter([0.0, 1.0, 1.0, 1.5])

    def on_call(_model, kind, idx):
        if kind == "ordinary":
            clock.set(0.0)
        else:
            clock.set(1.0)
            _model._advance_to = 1.5

    # Use the recorder to stamp exact start/end ticks per invocation instead.
    graph = _graph(tmp_path, monkeypatch, model, callbacks=[recorder, handler],
                   max_tool_rounds=1)
    _run_with_clock(graph, clock, ["market"])

    starts = recorder.starts()
    by_key = {e["agent_key"] for e in starts}
    assert by_key == {"market"}, [e for e in starts]
    assert all(e["scope"] == "analyst" for e in starts)
    assert _has_ordinary_and_wrap_up(recorder)

    row = _row(handler.get_agent_stats(), "market")
    assert row["calls"] == 2
    assert row["input_tokens"] == {"value": 180, "status": "complete"}
    assert row["output_tokens"] == {"value": 35, "status": "complete"}
    assert row["duration"] == pytest.approx(1.5)


def _has_ordinary_and_wrap_up(recorder):
    """True when both an ordinary (tool-bound) and a wrap_up call were observed."""
    nodes = [e["node"] for e in recorder.starts()]
    return any(n == "wrap_up" for n in nodes)


