def wait_until_later_ordinary_terminates(self, agent_key: str) -> None:
    """Block if ``agent_key`` was the earlier ordinary starter, until the
    later ordinary starter's terminal callback has been recorded."""
    if self.order_latch is None:
        return
    # Wait (bounded) until both ordinary starts have been recorded by the
    # callback, so the start order reflects actual model-start callbacks.
    deadline = threading.Event()
    while True:
        with self.lock:
            if len(self._ordinary_start_order) >= 2:
                first, second = self._ordinary_start_order[0], self._ordinary_start_order[1]
                break
        if deadline.wait(0.005) and self._later_terminal.is_set():
            raise AssertionError("both ordinary starts not observed")
    if agent_key == first:
        if not self._later_terminal.wait(timeout=10):
            raise AssertionError("later ordinary starter did not terminate in time")
    # The later starter returns immediately (it will terminate first).

